package bowling

import "errors"

var (
	errNegativeRoll     = errors.New("Negative roll is invalid")
	errPinCountExceeded = errors.New("Pin count exceeds pins on the lane")
	errGameOver         = errors.New("Cannot roll after game is over")
	errIncompleteGame   = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of a bowling game, frame by frame.
type Game struct {
	rolls []int // every roll in the order it was made
	frame int   // index of the frame currently being played (0-9)
	cur   []int // rolls made in the current frame
}

func NewGame() *Game {
	return &Game{}
}

// gameOver reports whether all ten frames have been completed.
func (g *Game) gameOver() bool {
	return g.frame >= 10
}

// frameComplete reports whether the current frame has all of its rolls.
func (g *Game) frameComplete() bool {
	if g.frame < 9 {
		return len(g.cur) == 2 || g.cur[0] == 10
	}
	// Tenth frame: an open frame ends after two rolls; a strike or spare
	// requires a third (fill) roll.
	if len(g.cur) == 3 {
		return true
	}
	return len(g.cur) == 2 && g.cur[0]+g.cur[1] < 10
}

// validateRoll checks that pins is legal for the current frame state.
func (g *Game) validateRoll(pins int) error {
	if g.frame < 9 {
		if len(g.cur) == 1 && pins > 10-g.cur[0] {
			return errPinCountExceeded
		}
		return nil
	}
	// Tenth frame.
	switch len(g.cur) {
	case 1:
		// After a strike the second roll is free; otherwise it must not
		// exceed the pins still standing.
		if g.cur[0] != 10 && pins > 10-g.cur[0] {
			return errPinCountExceeded
		}
	case 2:
		// Third (fill) roll. If the first roll was a strike and the second
		// was not, the two together cannot exceed ten pins.
		if g.cur[0] == 10 && g.cur[1] != 10 && pins > 10-g.cur[1] {
			return errPinCountExceeded
		}
	}
	return nil
}

func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errPinCountExceeded
	}
	if g.gameOver() {
		return errGameOver
	}
	if err := g.validateRoll(pins); err != nil {
		return err
	}

	g.rolls = append(g.rolls, pins)
	g.cur = append(g.cur, pins)
	if g.frameComplete() {
		g.frame++
		g.cur = nil
	}
	return nil
}

func (g *Game) Score() (int, error) {
	if !g.gameOver() {
		return 0, errIncompleteGame
	}

	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if frame < 9 {
			if g.rolls[i] == 10 {
				// Strike: ten plus the next two rolls.
				total += 10 + g.rolls[i+1] + g.rolls[i+2]
				i++
			} else if g.rolls[i]+g.rolls[i+1] == 10 {
				// Spare: ten plus the next roll.
				total += 10 + g.rolls[i+2]
				i += 2
			} else {
				total += g.rolls[i] + g.rolls[i+1]
				i += 2
			}
		} else {
			// Tenth frame: the total of its own rolls (including fills).
			for ; i < len(g.rolls); i++ {
				total += g.rolls[i]
			}
		}
	}
	return total, nil
}

